use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl SyntaxContext { # [inline] pub const fn root () -> Self { SyntaxContext (0) } # [inline] pub const fn is_root (self) -> bool { self . 0 == SyntaxContext :: root () . as_u32 () } # [inline] pub (crate) const fn as_u32 (self) -> u32 { self . 0 } # [inline] pub (crate) const fn from_u32 (raw : u32) -> SyntaxContext { SyntaxContext (raw) } # [inline] pub (crate) const fn from_u16 (raw : u16) -> SyntaxContext { SyntaxContext (raw as u32) } # [inline] fn from_usize (raw : usize) -> SyntaxContext { SyntaxContext (u32 :: try_from (raw) . unwrap ()) } # [doc = " Extend a syntax context with a given expansion and transparency."] # [inline] pub fn apply_mark (self , expn_id : ExpnId , transparency : Transparency) -> SyntaxContext { HygieneData :: with (| data | data . apply_mark (self , expn_id , transparency)) } # [doc = " Pulls a single mark off of the syntax context. This effectively moves the"] # [doc = " context up one macro definition level. That is, if we have a nested macro"] # [doc = " definition as follows:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " macro_rules! f {"] # [doc = "    macro_rules! g {"] # [doc = "        ..."] # [doc = "    }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " and we have a SyntaxContext that is referring to something declared by an invocation"] # [doc = " of g (call it g1), calling remove_mark will result in the SyntaxContext for the"] # [doc = " invocation of f that created g1."] # [doc = " Returns the mark that was removed."] # [inline] pub fn remove_mark (& mut self) -> ExpnId { HygieneData :: with (| data | data . remove_mark (self) . 0) } # [inline] pub fn marks (self) -> Vec < (ExpnId , Transparency) > { HygieneData :: with (| data | data . marks (self)) } # [doc = " Adjust this context for resolution in a scope created by the given expansion."] # [doc = " For example, consider the following three resolutions of `f`:"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(decl_macro)]"] # [doc = " mod foo {"] # [doc = "     pub fn f() {} // `f`'s `SyntaxContext` is empty."] # [doc = " }"] # [doc = " m!(f);"] # [doc = " macro m($f:ident) {"] # [doc = "     mod bar {"] # [doc = "         pub fn f() {} // `f`'s `SyntaxContext` has a single `ExpnId` from `m`."] # [doc = "         pub fn $f() {} // `$f`'s `SyntaxContext` is empty."] # [doc = "     }"] # [doc = "     foo::f(); // `f`'s `SyntaxContext` has a single `ExpnId` from `m`"] # [doc = "     //^ Since `mod foo` is outside this expansion, `adjust` removes the mark from `f`,"] # [doc = "     //| and it resolves to `::foo::f`."] # [doc = "     bar::f(); // `f`'s `SyntaxContext` has a single `ExpnId` from `m`"] # [doc = "     //^ Since `mod bar` not outside this expansion, `adjust` does not change `f`,"] # [doc = "     //| and it resolves to `::bar::f`."] # [doc = "     bar::$f(); // `f`'s `SyntaxContext` is empty."] # [doc = "     //^ Since `mod bar` is not outside this expansion, `adjust` does not change `$f`,"] # [doc = "     //| and it resolves to `::bar::$f`."] # [doc = " }"] # [doc = " ```"] # [doc = " This returns the expansion whose definition scope we use to privacy check the resolution,"] # [doc = " or `None` if we privacy check as usual (i.e., not w.r.t. a macro definition scope)."] # [inline] pub fn adjust (& mut self , expn_id : ExpnId) -> Option < ExpnId > { HygieneData :: with (| data | data . adjust (self , expn_id)) } # [doc = " Like `SyntaxContext::adjust`, but also normalizes `self` to macros 2.0."] # [inline] pub (crate) fn normalize_to_macros_2_0_and_adjust (& mut self , expn_id : ExpnId) -> Option < ExpnId > { HygieneData :: with (| data | { * self = data . normalize_to_macros_2_0 (* self) ; data . adjust (self , expn_id) }) } # [doc = " Adjust this context for resolution in a scope created by the given expansion"] # [doc = " via a glob import with the given `SyntaxContext`."] # [doc = " For example:"] # [doc = ""] # [doc = " ```compile_fail,E0425"] # [doc = " #![feature(decl_macro)]"] # [doc = " m!(f);"] # [doc = " macro m($i:ident) {"] # [doc = "     mod foo {"] # [doc = "         pub fn f() {} // `f`'s `SyntaxContext` has a single `ExpnId` from `m`."] # [doc = "         pub fn $i() {} // `$i`'s `SyntaxContext` is empty."] # [doc = "     }"] # [doc = "     n!(f);"] # [doc = "     macro n($j:ident) {"] # [doc = "         use foo::*;"] # [doc = "         f(); // `f`'s `SyntaxContext` has a mark from `m` and a mark from `n`"] # [doc = "         //^ `glob_adjust` removes the mark from `n`, so this resolves to `foo::f`."] # [doc = "         $i(); // `$i`'s `SyntaxContext` has a mark from `n`"] # [doc = "         //^ `glob_adjust` removes the mark from `n`, so this resolves to `foo::$i`."] # [doc = "         $j(); // `$j`'s `SyntaxContext` has a mark from `m`"] # [doc = "         //^ This cannot be glob-adjusted, so this is a resolution error."] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = " This returns `None` if the context cannot be glob-adjusted."] # [doc = " Otherwise, it returns the scope to use when privacy checking (see `adjust` for details)."] pub (crate) fn glob_adjust (& mut self , expn_id : ExpnId , glob_span : Span ,) -> Option < Option < ExpnId > > { HygieneData :: with (| data | { let mut scope = None ; let mut glob_ctxt = data . normalize_to_macros_2_0 (glob_span . ctxt ()) ; while ! data . is_descendant_of (expn_id , data . outer_expn (glob_ctxt)) { scope = Some (data . remove_mark (& mut glob_ctxt) . 0) ; if data . remove_mark (self) . 0 != scope . unwrap () { return None ; } } if data . adjust (self , expn_id) . is_some () { return None ; } Some (scope) }) } # [doc = " Undo `glob_adjust` if possible:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " if let Some(privacy_checking_scope) = self.reverse_glob_adjust(expansion, glob_ctxt) {"] # [doc = "     assert!(self.glob_adjust(expansion, glob_ctxt) == Some(privacy_checking_scope));"] # [doc = " }"] # [doc = " ```"] pub (crate) fn reverse_glob_adjust (& mut self , expn_id : ExpnId , glob_span : Span ,) -> Option < Option < ExpnId > > { HygieneData :: with (| data | { if data . adjust (self , expn_id) . is_some () { return None ; } let mut glob_ctxt = data . normalize_to_macros_2_0 (glob_span . ctxt ()) ; let mut marks = Vec :: new () ; while ! data . is_descendant_of (expn_id , data . outer_expn (glob_ctxt)) { marks . push (data . remove_mark (& mut glob_ctxt)) ; } let scope = marks . last () . map (| mark | mark . 0) ; while let Some ((expn_id , transparency)) = marks . pop () { * self = data . apply_mark (* self , expn_id , transparency) ; } Some (scope) }) } pub fn hygienic_eq (self , other : SyntaxContext , expn_id : ExpnId) -> bool { HygieneData :: with (| data | { let mut self_normalized = data . normalize_to_macros_2_0 (self) ; data . adjust (& mut self_normalized , expn_id) ; self_normalized == data . normalize_to_macros_2_0 (other) }) } # [inline] pub fn normalize_to_macros_2_0 (self) -> SyntaxContext { HygieneData :: with (| data | data . normalize_to_macros_2_0 (self)) } # [inline] pub fn normalize_to_macro_rules (self) -> SyntaxContext { HygieneData :: with (| data | data . normalize_to_macro_rules (self)) } # [doc = " See [`SyntaxContextData::outer_expn`]"] # [inline] pub fn outer_expn (self) -> ExpnId { HygieneData :: with (| data | data . outer_expn (self)) } # [doc = " `ctxt.outer_expn_data()` is equivalent to but faster than"] # [doc = " `ctxt.outer_expn().expn_data()`."] # [inline] pub fn outer_expn_data (self) -> ExpnData { HygieneData :: with (| data | data . expn_data (data . outer_expn (self)) . clone ()) } # [doc = " See [`HygieneData::outer_mark`]"] # [inline] fn outer_mark (self) -> (ExpnId , Transparency) { HygieneData :: with (| data | data . outer_mark (self)) } # [inline] pub (crate) fn dollar_crate_name (self) -> Symbol { HygieneData :: with (| data | data . syntax_context_data [self . 0 as usize] . dollar_crate_name) } # [inline] pub fn edition (self) -> Edition { HygieneData :: with (| data | data . expn_data (data . outer_expn (self)) . edition) } # [doc = " Returns whether this context originates in a foreign crate's external macro."] # [doc = ""] # [doc = " This is used to test whether a lint should not even begin to figure out whether it should"] # [doc = " be reported on the current node."] pub fn in_external_macro (self , sm : & SourceMap) -> bool { let expn_data = self . outer_expn_data () ; match expn_data . kind { ExpnKind :: Root | ExpnKind :: Desugaring (DesugaringKind :: ForLoop | DesugaringKind :: WhileLoop | DesugaringKind :: OpaqueTy | DesugaringKind :: Async | DesugaringKind :: Await ,) => false , ExpnKind :: AstPass (_) | ExpnKind :: Desugaring (_) => true , ExpnKind :: Macro (MacroKind :: Bang , _) => { expn_data . def_site . is_dummy () || sm . is_imported (expn_data . def_site) } ExpnKind :: Macro { .. } => true , } } }